damaged_code:
```rust
// System Version 1 schema does not know about photo_url
#[derive(serde::Deserialize, serde::Serialize)]
struct PersonV1 {
    user_name: String,
    favorite_number: u64,
}

// Old service instance reads a document containing {"user_name": "Martin", "favorite_number": 1337, "photo_url": "http://..."}
fn update_user_preferences(db_json: &str) -> String {
    let mut p: PersonV1 = serde_json::from_str(db_json).unwrap(); // Silently discards photo_url
    p.favorite_number = 42;
    serde_json::to_string(&p).unwrap() // photo_url is permanently deleted upon write-back!
}
```

counterexample:
```rust
// Valid: Using a schema-driven serializer that preserves unknown fields, or updating via targeted field set
#[derive(serde::Deserialize, serde::Serialize)]
struct PersonV1 {
    user_name: String,
    favorite_number: u64,
    #[serde(flatten)]
    extra_fields: std::collections::HashMap<String, serde_json::Value>, // Preserves extra fields
}
```
